function save(){try{sessionStorage.setItem(KEY,JSON.stringify({answers,index}));}catch{storageAvailable=false;const status=document.querySelector('#backup-status');if(status)status.textContent=tr('This browser cannot save progress. Download an answer file before leaving.','Nettleseren kan ikke lagre fremdrift. Last ned en svarfil før du forlater siden.');}document.querySelector('#backup-save')?.removeAttribute('disabled');}
function downloadAnswers(){
  if(!Object.keys(answers).length)return;
  const url=URL.createObjectURL(new Blob([encodeAnswers(answers,index)],{type:'application/json'}));
  const link=document.createElement('a');link.href=url;link.download='kaleido-answers.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
async function restoreAnswers(file){
  if(!file)return;
  const token=++restoreToken;
  const status=document.querySelector('#backup-status');
  try{
    if(file.size>65536)throw Error('File too large');
    const text=await file.text();
    if(token!==restoreToken)return;
    const saved=decodeAnswers(text,questions);
    if(Object.keys(answers).length&&!confirm(tr('Replace the answers in this tab with the saved file?','Erstatte svarene i denne fanen med den lagrede filen?')))return;
    answerToken++;busy=false;answers=saved.answers;index=saved.index;report=null;demo=false;save();
    backupMessage=tr('Your saved answers are restored. The report uses the current version.','De lagrede svarene er hentet inn. Rapporten bruker gjeldende versjon.');
    const target=Object.keys(answers).length===120?'#report':'#test';
    if(location.hash===target)render();else location.hash=target;
  }catch{if(token!==restoreToken)return;status.textContent=tr('This file is not a valid Kaleido answer backup. Your current answers have not changed.','Filen er ikke en gyldig Kaleido-svarkopi. Svarene dine er ikke endret.');}
}
function sorted(){return report.domains;}
function bandText(b){if(report?.norms)return b==='low'?tr('Lower range','Lavere område'):b==='high'?tr('Higher range','Høyere område'):tr('Middle range','Midtre område');return b==='low'?tr('Lower on the scale','Lavere på skalaen'):b==='high'?tr('Higher on the scale','Høyere på skalaen'):tr('Middle of the scale','Midt på skalaen');}
function entry(d){const base=content.domains?.[d.code]||{};return {...(base[d.band]||{}),...(d.content||{})};}
function name(d){return content.domains?.[d.code]?.name||names[d.code]?.()||d.name;}
function scale(d){return `<div class="score-row"><div class="score-top"><strong>${esc(name(d))}</strong><span>${Number(d.mean).toFixed(2)} / 5</span></div><div class="track" role="img" aria-label="${esc(name(d))}: ${Number(d.mean).toFixed(2)} / 5"><span style="width:${Math.max(0,Math.min(100,d.position))}%"></span></div><div class="score-scale"><span>${tr('Lower endorsement','Lavere tilslutning')}</span><span>${tr('Higher endorsement','Høyere tilslutning')}</span></div></div>`;}
function notice(){return demo?`<div class="notice demo">${tr('Synthetic example — these are invented answers, not your personal results.','Syntetisk eksempel — svarene er oppdiktet og er ikke dine personlige resultater.')}</div>`:'';}
function interpretation(){return (report?report.norms:norms)?tr('Each bar shows a percentile: roughly where your score sits among US online respondents who took the English test, with equal scores shared in the ranking. A percentile is not a percentage of a trait, a diagnosis, or a measure of how certain the result is. The words lower, middle and higher follow the percentile: below 30 is lower, above 70 is higher. Traits are tendencies, and context matters.','Hver stolpe viser en persentil: omtrent hvor skåren din ligger blant amerikanske nettdeltakere som tok den engelske testen, der like skårer deles i rangeringen. En persentil er ikke prosent av et trekk, en diagnose eller et mål på hvor sikker målingen er. Ordene lavere, midt og høyere følger persentilen: under 30 er lavere, over 70 er høyere. Trekk er tendenser, og situasjonen betyr noe.'):tr('These scales describe your answers, not your rank among other people. The bar maps the mean from 1 to 5 onto its possible range; it is not a percentile. Traits are tendencies, and context matters.','Skalaene beskriver svarene dine, ikke plasseringen din sammenlignet med andre. Stolpen viser gjennomsnittet ditt på skalaen fra 1 til 5; den er ikke en persentil. Trekk er tendenser, og situasjonen betyr noe.');}
function updateShell(){document.documentElement.lang=language==='no'?'nb':'en';document.title=tr('Free Big Five personality test – 120 questions | Kaleido','Gratis personlighetstest (Big Five) – 120 spørsmål | Kaleido');document.querySelector('nav').innerHTML=`<a href="#method">${tr('The science','Faglig grunnlag')}</a>${account.enabled()||devMode()||answersComplete()?`<a href="#account">${tr('My profile','Min side')}</a>`:''}${myCharacter()?'':`<a class="small-button" href="#test">${tr('Take the test','Ta testen')} →</a>`}<a class="d-exit" href="#home">${tr('Exit the test','Avslutt testen')}</a>`;document.querySelector('.skip').textContent=tr('Skip to content','Hopp til innhold');document.querySelector('footer').innerHTML=`<a class="footer-brand" href="#home" aria-label="Kaleido">${wordmark} <span>${tr('Your personality, in context.','Personligheten din, i sammenheng.')}</span></a><div><label>${tr('Language','Språk')} <select id="language" aria-label="${tr('Language','Språk')}"><option value="en" ${language==='en'?'selected':''}>English</option><option value="no" ${language==='no'?'selected':''}>Norsk bokmål</option></select></label><label>${tr('Country','Land')} <select id="country" aria-label="${tr('Country','Land')}"><option value="US" ${country==='US'?'selected':''}>USA · USD</option><option value="NO" ${country==='NO'?'selected':''}>Norge · NOK</option></select></label></div><div><button class="text-button" id="backup-save" ${Object.keys(answers).length?'':'disabled'}>${tr('Save my answers to a file','Lagre svarene mine i en fil')}</button><button class="text-button" id="backup-open">${tr('Restore saved answers','Hent lagrede svar')}</button><input id="backup-restore" type="file" accept=".json,application/json" hidden><p id="backup-status" role="status">${esc(backupMessage)||(storageAvailable?'':tr('Progress cannot be saved in this tab. Download an answer file before leaving.','Fremdrift kan ikke lagres i fanen. Last ned en svarfil før du forlater siden.'))}</p><a href="#method">${tr('Method & sources','Metode og kilder')}</a><a href="#legal">${tr('Legal','Juridisk')}</a><button id="clear-data" class="text-button">${tr('Clear my answers','Slett svarene mine')}</button></div><p>${tr('Preview. Country and language initially follow your browser language; change them independently above. No location tracking.','Forhåndsvisning. Land og språk velges først ut fra nettleserspråket; du kan endre dem hver for seg ovenfor. Ingen stedssporing.')}</p>`;document.querySelector('#backup-open').onclick=()=>document.querySelector('#backup-restore').click();document.querySelector('#backup-save').onclick=downloadAnswers;document.querySelector('#backup-restore').onchange=e=>restoreAnswers(e.target.files[0]);const controls=document.createElement('div');controls.className='locale-bar';controls.innerHTML=`<label>${tr('Language','Språk')} <select id="header-language" aria-label="${tr('Language','Språk')}"><option value="en" ${language==='en'?'selected':''}>English</option><option value="no" ${language==='no'?'selected':''}>Norsk bokmål</option></select></label><label>${tr('Country','Land')} <select id="header-country" aria-label="${tr('Country','Land')}"><option value="US" ${country==='US'?'selected':''}>USA · USD</option><option value="NO" ${country==='NO'?'selected':''}>Norge · NOK</option></select></label>`;document.querySelector('.locale-bar')?.remove();document.querySelector('header').append(controls);document.querySelector('.menu-toggle')?.remove();const head=document.querySelector('header');head.classList.remove('menu-open');const toggle=document.createElement('button');toggle.type='button';toggle.className='menu-toggle';toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label',tr('Menu','Meny'));toggle.innerHTML='<span></span><span></span><span></span>';toggle.onclick=()=>toggle.setAttribute('aria-expanded',head.classList.toggle('menu-open'));head.append(toggle);paintAvatar();document.querySelector('#header-language').onchange=async e=>{language=e.target.value;storePrefs();await load();};document.querySelector('#header-country').onchange=e=>{country=e.target.value;storePrefs();render(false);};document.querySelector('#language').onchange=async e=>{language=e.target.value;storePrefs();await load();};document.querySelector('#country').onchange=e=>{country=e.target.value;storePrefs();render(false);};document.querySelector('#clear-data').onclick=()=>{if(confirm(tr('Delete all your answers and results from this tab?','Slette alle svarene og resultatene dine fra denne fanen?'))){restoreToken++;answerToken++;busy=false;backupMessage='';answers={};index=0;report=null;demo=false;try{sessionStorage.removeItem(KEY);sessionStorage.removeItem(STEPS);}catch{}clearLife();clearCareer();account.forgetAnswers();location.hash='home';render();}};}
// Once the test is done, «Take the test» gives way to the person's own badge in the top corner: their
// profile character with their initials from the sign-in (Rune 2026-10-18). It links to «Min side», the overview.
function myCharacter(){if(demo||!answersComplete())return null;if(!report)try{calculate();}catch{return null;}return profileName(sorted(),language);}
const initials=()=>{const n=String(accountUser?.name||'').trim().split(/\s+/).filter(Boolean);return (n.length?(n.length>1?n[0][0]+n.at(-1)[0]:n[0][0]):String(accountUser?.email||'')[0]||'').toUpperCase();};
// The badge is the reveal's last step (Rune 2026-10-20): not on the sign-in step or the loader, not before sign-in,
// and not until the profile video has been seen or closed.
function badgeReady(){const route=(location.hash||'#home').slice(1);if(['test','signin','loading'].includes(route)||(account.enabled()&&!accountUser))return false;
  try{if(sessionStorage.getItem(INTRO)==='1')return false;}catch{}return !document.querySelector('dialog.d-video-intro');}
function paintAvatar(){const head=document.querySelector('header');head.querySelector('.d-avatar')?.remove();const me=badgeReady()&&myCharacter();if(!me)return;
  const a=document.createElement('a'),ini=initials();a.className='d-avatar';a.href='#account';a.setAttribute('aria-label',tr('Your profile','Profilen din'));
  a.innerHTML=`<span class="d-avatar-pic"><img src="${figureSrc(me.image)}" data-id="${me.image}" alt=""></span>${ini?`<span class="d-avatar-initials" aria-hidden="true">${esc(ini)}</span>`:''}`;
  head.insertBefore(a,head.querySelector('.menu-toggle'));}
function storePrefs(){try{localStorage.setItem(PREF,JSON.stringify({language,country}));}catch{}}
async function loadNorms(){try{const r=await fetch('data/norms-us.json');return r.ok?await r.json():null;}catch{return null;}}
async function load(){const token=++loadToken;try{const paths=language==='no'?['data/questions-no.json','data/report-content-no.json']:['data/questions.json','data/report-content.json'];const data=await Promise.all(paths.map(async p=>{const r=await fetch(p);if(!r.ok)throw Error(p);return r.json();}));if(norms===undefined)norms=await loadNorms();if(token!==loadToken)return;questions=data[0];content=data[1];if(questions.length!==120)throw Error('Expected 120 questions');answers=Object.fromEntries(Object.entries(answers).filter(([k,v])=>questions.some(q=>String(q.id)===k)&&Number.isInteger(v)&&v>=1&&v<=5));index=Math.min(Math.max(index,0),119);if(report)calculate(demo);render();}catch(e){if(token!==loadToken)return;main.innerHTML=`<div class="error"><h1>${tr('A small interruption','En liten avbrytelse')}</h1><p>${tr('The assessment could not load. Please serve the app through its local web server and try again. Your existing answers have not been cleared.','Testen kunne ikke lastes. Åpne appen gjennom den lokale nettserveren og prøv igjen. Lagrede svar er ikke slettet.')}</p><button class="button" id="retry">${tr('Try again','Prøv igjen')}</button></div>`;document.querySelector('#retry').onclick=load;console.error(e);}}
function home(){const cta=tr('Start the test','Start testen'),pieces={O:'sky',C:'apricot',E:'steel',A:'ivory',N:'navy'},sample=[62,57,59,66,51],side=(t,cls)=>`<p class="h-side ${cls}" aria-hidden="true">${t}</p>`;main.innerHTML=`<section class="h-hero"><div class="h-hero-text"><p class="h-eyebrow">${tr('Know yourself better','Kjenn deg selv bedre')}</p><h1>${tr('See every<br>side of you.','Se alle<br>sidene dine.')}</h1><p class="h-lead">${tr('Explore your personality with the Big Five.','Utforsk personligheten din med Big Five.')}</p>${button(cta,'#test')}<p class="h-hint">${tr('Free profile · 120 questions · 10 minutes','Gratis profil · 120 spørsmål · 10 minutter')}</p></div><div class="h-hero-art"><img src="assets/design/home-hero.webp" alt="" aria-hidden="true">${side(tr('Same<br>people.<br>More<br>perspectives.','Samme<br>mennesker.<br>Flere<br>perspektiver.'),'h-side-right')}</div></section><section class="h-traits"><div class="h-traits-head"><div><h2>${tr('Five traits. Thirty facets. One you.','Fem trekk. Tretti fasetter. Én deg.')}</h2></div><p class="h-example">${tr('Illustrative example','Illustrert eksempel')}</p></div><ul class="h-band">${order.map((c,i)=>`<li class="h-tile h-${c}" style="--i:${i};--bar:${traitColors[c]}"><img src="assets/design/logo-piece-${pieces[c]}.webp" alt="" aria-hidden="true"><span class="h-name">${names[c]()}</span><span class="h-bar" role="img" aria-label="${tr(`Example: ${sample[i]} of 100`,`Eksempel: ${sample[i]} av 100`)}"><span style="width:${sample[i]}%"></span><i style="left:${sample[i]}%"></i></span></li>`).join('')}</ul></section><section class="h-areas"><h2>${tr('What would you like to understand?','Hva vil du forstå bedre?')}</h2><div class="h-cards">${[['life',tr('Everyday life','Hverdagen'),tr('Habits and choices.','Vaner og valg.')],['relations',tr('Your relationships','Relasjonene dine'),tr('You and other people.','Deg i møte med andre.')],['work',tr('Work & career','Arbeidsliv og karriere'),tr('The way you work.','Måten du jobber på.')]].map(([k,h,p])=>`<a class="h-card" href="#test"><img src="assets/design/home-card-${k}.webp" alt="" aria-hidden="true"><h3>${h}</h3><p>${p}</p><span class="h-arrow" aria-hidden="true">→</span></a>`).join('')}</div></section><section class="h-closing"><div class="h-closing-text"><p class="h-eyebrow">${tr('See your pattern.','Se mønsteret ditt.')}</p><h2>${tr('Curious about who you are?','Nysgjerrig på hvem du er?')}</h2><div class="h-closing-actions">${button(cta,'#test')}</div></div><img class="h-burst" src="assets/design/logo-spread.webp" alt="" aria-hidden="true">${side(tr('Same<br>facts.<br>More<br>possibilities.','Samme<br>fakta.<br>Flere<br>muligheter.'),'h-side-cta')}</section>`;}
// Test helper for previews: ?dev=1 shows a small "Random" button on the question page (remembered in this
// browser; ?dev=0 turns it off). Remove before launch, see docs/plan.md.
// Until launch the «Random» test shortcut shows for everyone (Rune 2026-10-14). Set to false, or remove devRandom and its buttons, before going live.
const SHOW_RANDOM=true;
const showRandom=()=>SHOW_RANDOM||devMode();
function devMode(){try{const v=new URLSearchParams(location.search).get('dev');if(v==='1')localStorage.setItem('fem-dev','1');if(v==='0')localStorage.removeItem('fem-dev');return localStorage.getItem('fem-dev')==='1';}catch{return false;}}
// Preview only: fills all 120 answers at random and takes the same way as a real finish (sign-in step, loading, video, free profile).
function devRandom(replace=false,fixed=null){answerToken++;answers=fixed?fixed:norms?.scales?sampleAnswers(questions,norms):Object.fromEntries(questions.map(q=>[q.id,1+Math.floor(Math.random()*5)]));index=119;demo=false;save();const to='#'+(askSignIn()?'signin':'loading');if(replace)location.replace(to);else location.hash=to;}
// Preview only: Rune's own test profile (app/dev-profile.js), so the career questions can be tried on it.
function devRune(replace=false){devRandom(replace,profileAnswers(questions,norms));}
// Cairns count the questions you have passed, so going back takes the last stone off again.
