function pieceLoaderHtml(cls,title,items,order=LOADER_PIECES,badge=''){return `<section class="d-loading d-opening ${cls}" role="status"><div class="d-assemble" aria-hidden="true">${order.map(c=>`<img class="d-piece d-tri-${c}" src="assets/design/logo-piece-${c}.webp" alt="">`).join('')}</div>${badge?`<p class="d-tailor-badge">${badge}</p>`:''}<h1>${title}</h1><div class="d-opening-meter" aria-hidden="true"><div class="d-opening-track"><span></span></div><b>0 %</b></div><ul class="d-opening-list">${items.map((t,i)=>`<li><img src="assets/design/logo-piece-${order[i]}.webp" alt="" aria-hidden="true">${t}</li>`).join('')}</ul></section>`;}
