  const show=(pct,step,done)=>{bar.style.width=pct+'%';num.textContent=pct+' %';imgs.forEach((im,i)=>{im.classList.toggle('is-lift',i===step&&!done);im.classList.toggle('is-done',i<step||(i===step&&done));});lis.forEach((li,i)=>li.classList.toggle('is-in',i<=step));};
