const money=n=>new Intl.NumberFormat(language==='no'?'nb-NO':'en-US',{style:'currency',currency:country==='NO'?'NOK':'USD',minimumFractionDigits:country==='NO'?0:2,maximumFractionDigits:country==='NO'?0:2}).format(country==='NO'?n[0]:n[1]);
// One line in the sheet about the buyer's own result (2026-10-18, evidence note): the two most distinctive traits
