  document.body.append(dlg);
  dlg.querySelectorAll('input[name="osheet-tier"]').forEach(r=>r.addEventListener('change',()=>dlg.querySelectorAll('.d-opay-btn').forEach(a=>{a.setAttribute('href',r.dataset.href);a.querySelector('.d-opay-amt').outerHTML=amt(r.value);})));
  dlg.querySelectorAll('.d-otier-more').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();const list=dlg.querySelector('#'+b.getAttribute('aria-controls')),open=list.hidden;list.hidden=!open;b.setAttribute('aria-expanded',open);b.closest('.d-otier').classList.toggle('is-open',open);}));
  // The report bought decides whether the tailored questions and the AI partner show (Rune 2026-10-18); both open on the overview.
  dlg.querySelectorAll('.d-opay-btn').forEach(a=>a.addEventListener('click',e=>{const t=dlg.querySelector('input[name="osheet-tier"]:checked')?.value;if(!account.paymentsOn()){setTier(t);return;}e.preventDefault();e.stopPropagation();startCheckout(dlg,a,t);}));
  const close=()=>{dlg.close();};dlg.addEventListener('close',()=>dlg.remove());
  dlg.querySelector('.d-osheet-close').addEventListener('click',close);
