// Links to the purchase page play the opening animation and then open the sheet; the full page stays at #offer for
// «See everything included». The two buttons on that page play their own report's version and choose that report.
document.addEventListener('click',e=>{const a=e.target.closest?.('a[href="#offer"]');if(!a||a.hasAttribute('data-full-offer')||e.metaKey||e.ctrlKey||e.shiftKey||typeof HTMLDialogElement!=='function')return;e.preventDefault();
  // A buyer goes straight to the report (Rune 2026-10-20); a 49 kr owner sees the upgrade only from links that offer it (data-tier="plus").
  if(account.paymentsOn()&&(purchased==='plus'||(purchased==='base'&&a.dataset.tier!=='plus'))){location.hash='report';return;}
  if(account.paymentsOn()&&purchased==='base'){openOfferSheet('plus');return;}
  offerPrep(a.dataset.tier||'plus');});
// Stripe Checkout: the server sets the price and sends back the hosted page's address (lib/payments.js).
async function startCheckout(dlg,btn,tier){if(btn.getAttribute('aria-busy')==='true')return;const err=dlg.querySelector('.d-opay-err');err.hidden=true;btn.setAttribute('aria-busy','true');dlg.querySelectorAll('.d-opay-btn').forEach(b=>b.classList.add('is-waiting'));
  try{const out=await account.purchase('checkout',{tier,market:country,lang:language,method:btn.dataset.method});
    if(out.url){location.assign(out.url);return;}
    if(out.tier){purchased=out.tier;dlg.close();location.hash='report';return;}
    throw new Error('no-url');}
  catch{err.textContent=tr('Could not open the payment page. Nothing was charged. Try again in a moment.','Fikk ikke åpnet betalingssiden. Ingenting er trukket. Prøv igjen om litt.');err.hidden=false;btn.removeAttribute('aria-busy');dlg.querySelectorAll('.d-opay-btn').forEach(b=>b.classList.remove('is-waiting'));}}
// Line icons for the purchase page (Rune's mockup, 2026-10-16).
